            WriteLiteral(@"
<script>
    function filterNotifications(filter) {
        // Update active tab
        document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
        event.target.classList.add('active');

        // Filter notifications
        const cards = document.querySelectorAll('.notification-card');
        cards.forEach(card => {
            if (filter === 'all' || card.dataset.status === filter) {
                card.style.display = 'flex';
            } else {
                card.style.display = 'none';
            }
        });
    }
</script>

<style>
    .notifications-container {
        padding: 40px 0;
        background: var(--bg-color);
        min-height: calc(100vh - 200px);
    }

    .page-header {
        text-align: center;
        margin-bottom: 32px;
    }

    .page-header h1 {
        font-size: 32px;
        margin-bottom: 8px;
    }

    .page-header p {
        color: var(--text-secondary);
    }

    .notifications-layout {
        display: grid;
        gri");
            WriteLiteral("d-template-columns: 2fr 1fr;\n        gap: 24px;\n    }\n\n    ");
            WriteLiteral(@"@media (max-width: 768px) {
        .notifications-layout {
            grid-template-columns: 1fr;
        }
    }

    .notifications-main {
        background: var(--card-bg);
        border-radius: 16px;
        overflow: hidden;
        box-shadow: var(--shadow);
    }

    .notifications-actions {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 16px 24px;
        border-bottom: 1px solid var(--border-color);
    }

    .filter-tabs {
        display: flex;
        gap: 8px;
    }

    .tab-btn {
        padding: 8px 16px;
        border: none;
        background: none;
        color: var(--text-secondary);
        font-size: 14px;
        font-weight: 500;
        cursor: pointer;
        border-radius: 8px;
        transition: all 0.2s;
    }

    .tab-btn.active {
        background: var(--primary-color);
        color: white;
    }

    .tab-btn:hover:not(.active) {
        background: var(--bg-color);
    }

    .btn-mark-all {
        pad");
            WriteLiteral(@"ding: 8px 16px;
        background: var(--primary-color);
        color: white;
        border: none;
        border-radius: 8px;
        font-size: 14px;
        font-weight: 500;
        cursor: pointer;
    }

    .notifications-list {
        padding: 16px;
    }

    .notification-card {
        display: flex;
        gap: 16px;
        padding: 16px;
        border-radius: 12px;
        margin-bottom: 12px;
        position: relative;
        transition: background 0.2s;
    }

    .notification-card.unread {
        background: var(--bg-color);
        border-left: 3px solid var(--primary-color);
